Task: Stack the red cube on top of the blue cube and let go.

Skill code (numbered):
  1| import math
  2| 
  3| def run(robot):
  4|     # Home to start cleanly
  5|     robot.home()
  6|     
  7|     # Get latest perception
  8|     obs = robot.observe()
  9|     red_pose = obs["objects"]["red_cube"]
 10|     blue_pose = obs["objects"]["blue_cube"]
 11|     
 12|     red_pos = red_pose["pos"]
 13|     blue_pos = blue_pose["pos"]
 14|     red_yaw = red_pose["yaw"]
 15|     blue_yaw = blue_pose["yaw"]
 16|     
 17|     CUBE_SIZE = 0.03          # side length
 18|     HALF = CUBE_SIZE / 2.0    # 0.015
 19|     GRASP_Z = HALF            # tool point height for grasping (finger pads around middle)
 20|     ABOVE_Z = 0.08            # safe height to approach/release
 21|     
 22|     # Helper to move with a given speed
 23|     def move(x, y, z, yaw=None, speed=0.15):
 24|         try:
 25|             return robot.move_to(x, y, z, yaw=yaw, speed=speed)
 26|         except Exception as e:
 27|             robot.log("MotionError:", e)
 28|             return {"ok": False}
 29|     
 30|     # 1. Move above red cube
 31|     move(red_pos[0], red_pos[1], ABOVE_Z, yaw=red_yaw, speed=0.15)
 32|     # 2. Lower to grasp height
 33|     move(red_pos[0], red_pos[1], GRASP_Z, yaw=red_yaw, speed=0.05)
 34|     # 3. Attempt grasp
 35|     if not robot.grasp():
 36|         robot.log("Grasp failed on red cube")
 37|         robot.home()
 38|         return False
 39|     # Verify hold
 40|     if robot.holding() != "red_cube":
 41|         robot.log("Not holding red cube after grasp")
 42|         robot.release()
 43|         robot.home()
 44|         return False
 45|     
 46|     # 4. Lift red cube
 47|     move(red_pos[0], red_pos[1], ABOVE_Z, yaw=red_yaw, speed=0.05)
 48|     
 49|     # 5. Move above blue cube
 50|     move(blue_pos[0], blue_pos[1], ABOVE_Z, yaw=blue_yaw, speed=0.15)
 51|     # 6. Lower to stacking height (blue cube top)
 52|     stack_z = blue_pos[2] + CUBE_SIZE  # center of red cube when stacked
 53|     move(blue_pos[0], blue_pos[1], stack_z, yaw=blue_yaw, speed=0.05)
 54|     # 7. Release
 55|     robot.release()
 56|     # Verify release
 57|     if robot.holding() is not None:
 58|         robot.log("Still holding after release")
 59|         robot.home()
 60|         return False
 61|     
 62|     # 8. Retreat
 63|     move(blue_pos[0], blue_pos[1], ABOVE_Z, yaw=blue_yaw, speed=0.05)
 64|     robot.home()
 65|     return True

